// Node kinds: 0 code (graphify's), 1 other file, 2 folder. Connection kinds:
// 0 between code, 1 the file and folder tree.
const kindOf = nodes.map(n => n[6])
const counts = D.stages.map((_, s) => {
  const files = new Set()
  let code = 0, folders = 0, links = 0
  nodes.forEach((node, i) => {
    if (!nodeIn[i][s]) return
    if (kindOf[i] === 2) folders++
    else { files.add(node[5]); if (kindOf[i] === 0) code++ }
  })
  edges.forEach((edge, e) => { if (edgeIn[e][s] && !edge[2]) links++ })
  return [folders, files.size, code, links]
})
const preGit = D.stages.findIndex(s => s.git)
