const rgb = hex => [1, 3, 5].map(k => parseInt(hex.slice(k, k + 2), 16)).join(',')
const colourOf = nodes.map(n => n[2])

// ---- Physics ---------------------------------------------------------------
// Every dot has a home: where graphify's page puts it (TX, TY). It is pulled
// there on a spring, connections pull their ends toward the distance their
// homes are apart, and dots too close push each other off. So new code shoots
// out from what it connects to and settles where graphify would show it,
// jostling its neighbours on the way -- the way Gource grows a tree.
const X = new Float32Array(N), Y = new Float32Array(N), VX = new Float32Array(N), VY = new Float32Array(N)
const TX = Float32Array.from(nodes, n => n[0]), TY = Float32Array.from(nodes, n => n[1])
const live = new Uint8Array(N)
// Held firmly to graphify's spot, so its shape survives -- tight clusters with
// empty space between them. Only dots that actually overlap are pushed apart;
// a longer reach spread every cluster to the same even density and filled the
// gaps, which is what turned the picture into a disc.
const HOME = 0.03, SPRING = 0.006, PUSH = 0.001, REACH = 0.012, DAMP = 0.85
const neighbours = Array.from({ length: N }, () => [])
const rest = new Float32Array(edges.length)
edges.forEach(([a, b], i) => {
  neighbours[a].push(b); neighbours[b].push(a)
  rest[i] = Math.hypot(TX[a] - TX[b], TY[a] - TY[b])
})

function spawn(i) {
  // Out of something already there that it connects to, as Gource's files
  // come out of their folder; failing that, near its own home.
  let from = -1
  for (const j of neighbours[i]) if (live[j]) { from = j; break }
  const a = Math.random() * Math.PI * 2
  const ox = from >= 0 ? X[from] : TX[i] + Math.cos(a) * 0.04
  const oy = from >= 0 ? Y[from] : TY[i] + Math.sin(a) * 0.04
  X[i] = ox + Math.cos(a) * 0.002; Y[i] = oy + Math.sin(a) * 0.002
  VX[i] = Math.cos(a) * 0.006; VY[i] = Math.sin(a) * 0.006
}

const grid = new Map()
function step(s) {
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    VX[i] += (TX[i] - X[i]) * HOME
    VY[i] += (TY[i] - Y[i]) * HOME
  }
  for (let e = 0; e < edges.length; e++) {
    // The file tree is drawn but doesn't pull: its lines run between clusters,
    // and as springs they drew the clusters together.
    if (!edgeIn[e][s] || edges[e][2]) continue
    const a = edges[e][0], b = edges[e][1]
    if (!live[a] || !live[b]) continue
    const dx = X[b] - X[a], dy = Y[b] - Y[a], d = Math.hypot(dx, dy) || 1e-6
    const f = SPRING * (d - rest[e]) / d * 0.5
    VX[a] += dx * f; VY[a] += dy * f; VX[b] -= dx * f; VY[b] -= dy * f
  }
  // Push apart what is too close, found through a grid so it isn't every pair.
  grid.clear()
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    const key = Math.floor(X[i] / REACH) * 100003 + Math.floor(Y[i] / REACH)
    const cell = grid.get(key)
    cell ? cell.push(i) : grid.set(key, [i])
  }
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    const gx = Math.floor(X[i] / REACH), gy = Math.floor(Y[i] / REACH)
    for (let ox = -1; ox <= 1; ox++) for (let oy = -1; oy <= 1; oy++) {
      const cell = grid.get((gx + ox) * 100003 + gy + oy)
      if (!cell) continue
      for (const j of cell) {
        if (j <= i) continue
        const d = Math.hypot(X[j] - X[i], Y[j] - Y[i])
        if (d >= REACH) continue
        // Along the line between them, never harder than PUSH. Two dots on the
        // very same spot get a random direction; dividing by their (zero)
        // distance used to fling them clean off the screen.
        const a = d > 1e-6 ? Math.atan2(Y[j] - Y[i], X[j] - X[i]) : Math.random() * Math.PI * 2
        const f = PUSH * (REACH - d) / REACH
        const fx = Math.cos(a) * f, fy = Math.sin(a) * f
        VX[i] -= fx; VY[i] -= fy; VX[j] += fx; VY[j] += fy
      }
    }
  }
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    VX[i] *= DAMP; VY[i] *= DAMP
    X[i] += VX[i]; Y[i] += VY[i]
  }
}

// ---- Camera ----------------------------------------------------------------
let W, H, dpr, home, view, follow = true, sideW = 0
function resize() {
  dpr = window.devicePixelRatio || 1
  W = innerWidth; H = innerHeight
  const side = document.getElementById('side')
  sideW = side.offsetWidth ? side.offsetWidth + 30 : 0
  canvas.width = W * dpr; canvas.height = H * dpr
  home = { x: W / 2, y: H / 2 - 10, s: Math.min(W, H - 110) * 0.47 }
  view = view || { ...home }
}
resize(); addEventListener('resize', resize)
const sx = i => view.x + X[i] * view.s, sy = i => view.y + Y[i] * view.s
const zoom = () => Math.min(2.2, Math.sqrt(view.s / home.s))

// Framing what exists, easing toward it: close in at the start, pulling back
// as the project grows.
function frameCamera(snap = false) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    if (X[i] < minX) minX = X[i]; if (X[i] > maxX) maxX = X[i]
    if (Y[i] < minY) minY = Y[i]; if (Y[i] > maxY) maxY = Y[i]
  }
  if (minX === Infinity) return
  const w = Math.max(maxX - minX, 0.25), h = Math.max(maxY - minY, 0.25)
  const s = Math.min((W - 80 - sideW) / w, (H - 230) / h)
  const target = { s, x: (W - sideW) / 2 - (minX + maxX) / 2 * s, y: (H + 10) / 2 - (minY + maxY) / 2 * s }
  const k = snap ? 1 : 0.035
  view.s += (target.s - view.s) * k
  view.x += (target.x - view.x) * k
  view.y += (target.y - view.y) * k
}

// ---- Time --------------------------------------------------------------------
let pos = 0, playing = false, prev = performance.now(), lag = 0
// About two and a half minutes for the whole history at 1x, whatever its
// length, but never so quick a change can't be seen to land.
const perStage = () => Math.min(330, Math.max(110, 150000 / S)) / Number(speedSel.value)
const ease = t => t * t * (3 - 2 * t)

// How visible something is between stage s and s+1, t of the way there:
// [alpha, state] where state 1 = arriving, -1 = leaving.
function fade(p, s, t) {
  const a = p[s], b = s < last ? p[s + 1] : a
  if (a && b) return [1, 0]
  if (!a && !b) return [0, 0]
  return a ? [1 - t, -1] : [t, 1]
}

function frame(now) {
  if (playing) {
    pos = Math.min(last, pos + (now - prev) / perStage())
    if (pos >= last) { playing = false; playLabel() }
    slider.value = pos
  }
  if (!introDone) opening(now)
  // Edits land as their stage starts arriving, with the new code beside them.
  for (let f = Math.floor(pos); introDone && lastFloor < f; ) {
    lastFloor++
    for (const i of changes[lastFloor + 1] || []) pulseAt[i] = now
  }
  // Physics on a fixed step, so it behaves the same at any frame rate.
  lag = Math.min(lag + (now - prev), 100)
  prev = now
  const s = Math.floor(pos)
  for (let i = 0; i < N; i++) {
    const on = nodeIn[i][s] || (s < last && nodeIn[i][s + 1])
    if (on && !live[i]) spawn(i)
    live[i] = on ? 1 : 0
  }
  while (lag >= 16) { step(s); lag -= 16 }
  if (follow) frameCamera()
  draw()
  requestAnimationFrame(frame)
}

// A connection bows slightly to one side, as graphify draws them: straight
// lines through a dense cluster read as a scribble, gentle curves as bundles.
function curve(a, b) {
  const x1 = sx(a), y1 = sy(a), x2 = sx(b), y2 = sy(b)
  ctx.moveTo(x1, y1)
  ctx.quadraticCurveTo((x1 + x2) / 2 - (y2 - y1) * 0.12, (y1 + y2) / 2 + (x2 - x1) * 0.12, x2, y2)
}

function draw() {
  const s = Math.floor(pos), t = ease(pos - s), z = zoom()
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  ctx.globalCompositeOperation = 'source-over'
  ctx.fillStyle = P.bg; ctx.fillRect(0, 0, W, H)

  // The file and folder tree first, faint, beneath the code.
  const width = 0.6 * z
  ctx.lineWidth = 0.5 * z
  ctx.strokeStyle = P.tree
  ctx.beginPath()
  const batches = new Map(), changing = []
  for (let e = 0; e < edges.length; e++) {
    const [alpha, state] = fade(edgeIn[e], s, t)
    if (!alpha) continue
    if (state) { changing.push([e, alpha, state]); continue }
    if (edges[e][2]) { const [a, b] = edges[e]; ctx.moveTo(sx(a), sy(a)); ctx.lineTo(sx(b), sy(b)); continue }
    const c = colourOf[edges[e][0]]
    const list = batches.get(c)
    list ? list.push(e) : batches.set(c, [e])
  }
  ctx.stroke()

  // The code's own connections, added together ('lighter') so a bundle glows
  // where many run side by side (on paper, multiplied, so it darkens). Batched
  // by colour; changing ones go alone.
  ctx.globalCompositeOperation = P.blend
  ctx.lineWidth = width
  for (const [c, list] of batches) {
    ctx.strokeStyle = `rgba(${rgb(c)},0.3)`
    ctx.beginPath()
    for (const e of list) curve(edges[e][0], edges[e][1])
    ctx.stroke()
  }
  ctx.lineWidth = width * 2
  for (const [e, alpha, state] of changing) {
    const [a, b] = edges[e]
    const k = edges[e][2] ? 0.45 : 1
    ctx.strokeStyle = state > 0 ? `rgba(${P.fresh},${0.85 * alpha * k})` : `rgba(${P.removed},${0.8 * alpha * k})`
    ctx.beginPath(); curve(a, b); ctx.stroke()
  }

  ctx.globalCompositeOperation = 'source-over'
  const arriving = []
  for (let i = 0; i < N; i++) {
    const [alpha, state] = fade(nodeIn[i], s, t)
    if (!alpha) continue
    // An edited piece swells a little and settles back -- up and down once,
    // over the pulse -- glowing while it does.
    const age = performance.now() - pulseAt[i], k = age < PULSE ? 1 - age / PULSE : 0
    const swell = k ? Math.sin(Math.PI * age / PULSE) : 0
    const kind = kindOf[i], x = sx(i), y = sy(i)
    const r = (kind === 2 ? 1.6 + Math.sqrt(nodes[i][3]) * 0.25 : kind === 1 ? 1 : 1 + Math.sqrt(nodes[i][3]) * 0.4) * z * (1 + 0.6 * swell)
    ctx.globalAlpha = alpha * (kind === 1 ? 0.6 : kind === 2 ? 0.55 : 1)
    if (kind === 2) {
      // Folders: small open squares, pale, so they read as the frame the
      // code hangs from rather than as code.
      ctx.strokeStyle = state < 0 ? `rgb(${P.removed})` : P.folder; ctx.lineWidth = 0.9
      ctx.strokeRect(x - r, y - r, r * 2, r * 2)
    } else {
      ctx.fillStyle = state < 0 ? `rgb(${P.removed})` : kind === 1 ? P.other : colourOf[i]
      ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill()
    }
    if (k && state === 0) {
      ctx.globalCompositeOperation = P.blend
      ctx.globalAlpha = 0.45 * swell
      ctx.fillStyle = kind === 2 ? P.folder : colourOf[i]
      ctx.beginPath(); ctx.arc(x, y, r + 4 * swell * z, 0, Math.PI * 2); ctx.fill()
      ctx.globalAlpha = 0.8 * swell
      ctx.fillStyle = P.ring
      ctx.beginPath(); ctx.arc(x, y, r * 0.8, 0, Math.PI * 2); ctx.fill()
      ctx.globalCompositeOperation = 'source-over'
    }
    if (state > 0) {
      arriving.push(i)
      ctx.globalAlpha = 1 - t
      ctx.strokeStyle = P.ring; ctx.lineWidth = 1.4
      ctx.beginPath(); ctx.arc(x, y, r + 1.5 + t * 9, 0, Math.PI * 2); ctx.stroke()
    }
  }
  // Names of what just arrived, as Gource shows its files -- unless a whole
  // batch lands at once, when they would only be a smear.
  if (arriving.length && arriving.length <= 30) {
    ctx.font = '11px ui-monospace, Consolas, monospace'
    ctx.globalAlpha = Math.min(1, 1.6 * (1 - t))
    ctx.fillStyle = P.label
    for (const i of arriving) if (nodes[i][4]) ctx.fillText(nodes[i][4], sx(i) + 6, sy(i) - 6)
  }
  ctx.globalAlpha = 1

  // Over the opening, the canvas is dimmed toward the background.
  if (veil) { ctx.globalAlpha = veil; ctx.fillStyle = P.bg; ctx.fillRect(0, 0, W, H); ctx.globalAlpha = 1 }

  const shown = Math.round(pos), stage = D.stages[shown]
  dateEl.textContent = new Date(stage.t * 1000).toISOString().slice(0, 16).replace('T', '  ')
  statsEl.textContent = tr.stats(...counts[shown])
  noteEl.textContent = stage.note
}

// ---- Controls ------------------------------------------------------------------
function playLabel() { playBtn.textContent = playing ? tr.pause : introDone && pos >= last ? tr.replay : tr.play }
function toggle() {
  if (pos >= last) { pos = 0; lastFloor = 0; live.fill(0); follow = true }
  playing = !playing
  playLabel()
}
playBtn.onclick = toggle
addEventListener('keydown', e => {
  if (!introDone) return
  if (e.code === 'Space') { e.preventDefault(); toggle() }
})
slider.oninput = () => { pos = Number(slider.value); lastFloor = Math.floor(pos); playing = false; playLabel() }

canvas.addEventListener('wheel', e => {
  e.preventDefault()
  follow = false
  const k = Math.exp(-e.deltaY * 0.0015)
  view.x = e.clientX - (e.clientX - view.x) * k
  view.y = e.clientY - (e.clientY - view.y) * k
  view.s *= k
}, { passive: false })
canvas.addEventListener('dblclick', () => { follow = true })
let drag = null
canvas.addEventListener('pointerdown', e => { drag = { x: e.clientX, y: e.clientY }; canvas.classList.add('dragging'); canvas.setPointerCapture(e.pointerId) })
canvas.addEventListener('pointerup', () => { drag = null; canvas.classList.remove('dragging') })
canvas.addEventListener('pointermove', e => {
  if (drag) {
    follow = false
    view.x += e.clientX - drag.x; view.y += e.clientY - drag.y
    drag = { x: e.clientX, y: e.clientY }; tip.style.display = 'none'; return
  }
  let best = -1, bestD = 64
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    const dx = sx(i) - e.clientX, dy = sy(i) - e.clientY, d = dx * dx + dy * dy
    if (d < bestD) { bestD = d; best = i }
  }
  if (best < 0) { tip.style.display = 'none'; return }
  tip.replaceChildren(nodes[best][4] || '(unnamed)')
  const small = document.createElement('small'); small.textContent = nodes[best][5] || tr.tip; tip.append(small)
  tip.style.display = 'block'
  tip.style.left = Math.min(e.clientX + 14, W - tip.offsetWidth - 8) + 'px'
  tip.style.top = (e.clientY + 14) + 'px'
})

// Opened from the landing page, this page is loaded ahead into a frame over it,
// unseen (src/lib/codeHistory.ts), and waits there to be shown: only then does
// it start, as if just opened. Its Back is the landing page's to do -- that
// slides home, where following the link would load the app all over again.
const start = () => requestAnimationFrame(t => { prev = t; frame(t) })
if (window.parent !== window) {
  let started = false
  addEventListener('message', e => {
    if (e.source !== parent || e.data !== 'code-history:show' || started) return
    started = true
    const now = storedLang()
    if (now && now !== lang) setLang(now, false)
    start()
  })
  document.getElementById('back').onclick = e => { e.preventDefault(); parent.postMessage('code-history:back', location.origin) }
  parent.postMessage('code-history:ready', location.origin)
} else start()

// The opening: the finished graph -- today's -- dimmed under two moments. First
// the name ("You're about to see the code history of THE DIGITAL ATRIUM"),
// in, held, out; then what follows, the same way; then an empty canvas, and
// from there the history grows, with the controls fading in. Only the Skip button cuts it short: a click anywhere, or
// a key, used to, which ended it for anyone who so much as touched the page.
const intro = document.getElementById('intro')
const introName = document.getElementById('introName'), introNext = document.getElementById('introNext')
// Each moment: in, held, out (ms) -- the name two seconds in all, what
// follows five.
const NAME = [450, 1150, 400], NEXT = [500, 4000, 500]
const NAME_END = NAME[0] + NAME[1] + NAME[2], OPEN_END = NAME_END + NEXT[0] + NEXT[1] + NEXT[2]
const shownAt = (t, [inn, hold, out]) => t < 0 ? 0 : t < inn ? ease(t / inn) : t < inn + hold ? 1 : ease(Math.max(0, 1 - (t - inn - hold) / out))
let introDone = false, openedAt = null, veil = 0

function opening(now) {
  if (openedAt === null) {
    openedAt = now
    pos = last
    for (let i = 0; i < N; i++) { live[i] = nodeIn[i][last]; X[i] = TX[i]; Y[i] = TY[i]; VX[i] = VY[i] = 0 }
    frameCamera(true)
  }
  const t = now - openedAt
  const name = shownAt(t, NAME), next = shownAt(t - NAME_END, NEXT)
  introName.style.opacity = name
  introNext.style.opacity = next
  // The graph stays a little dim behind the words, so they read, and sinks
  // back between the two moments as one goes and the other comes.
  veil = 1 - 0.55 * Math.max(name, next)
  if (t >= OPEN_END) endIntro()
}

function endIntro() {
  if (introDone) return
  introDone = true
  veil = 0
  intro.remove()
  skipBtn.remove()
  pos = 0; lastFloor = 0; live.fill(0); view = { ...home }; follow = true
  document.body.classList.remove('intro')
  if (!playing) toggle()
}
const skipBtn = document.getElementById('skip')
skipBtn.onclick = endIntro

// The words, now that everything they go into is here.
setLang(lang, false)
